contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run() public payable {
        require(true);

        IVaultAdapter.SlopeData memory slopes = IVaultAdapter.SlopeData({
            kink: 5e26,
            slope0: 1e16,
            slope1: 2e16
        });
        c.setSlopes(address(this), slopes);

        uint256 maxMultiplier = 2e27;
        uint256 minMultiplier = 1e26;
        uint256 rateLimit = 1e15;
        c.setLimits(maxMultiplier, minMultiplier, rateLimit);

        uint256 latestAnswer = c.rate(address(this), address(this));

        uint256 expected = slopes.slope0 * 1e27 / slopes.kink * minMultiplier / 1e27;
        assert(latestAnswer == expected);
    }

    receive() external payable {}
}

