contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address accessControl, address asset, uint256 kink, uint256 slope0, uint256 slope1) public payable {
        bool initialized;
        try c.initialize(accessControl) {
            initialized = true;
        } catch {
            initialized = false;
        }
        require(initialized, "initialize must succeed on fresh deployment");

        bool reverted;
        try c.setSlopes(asset, IVaultAdapter.SlopeData({kink: kink, slope0: slope0, slope1: slope1})) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (kink == 0 || kink >= 1e27) {
            assert(reverted);
        } else {
            assert(!reverted);
        }
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address accessControl, address asset, uint256 kink, uint256 slope0, uint256 slope1) public payable {
        c.initialize(accessControl);

        bool reverted;
        try c.setSlopes(asset, IVaultAdapter.SlopeData({kink: kink, slope0: slope0, slope1: slope1})) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert((kink == 0 || kink >= 1e27) == reverted);
    }
}

